# Surah At-Tawbah (chapter 9) — part 8: ayat 69-74 (IDs 1304-1309)
SURAH = 9

ENTRIES = {
1304: (
"جیسے — تم — سے — پہلے والے — وہ — تمہارے سے — زیادہ طاقتور — اور — زیادہ مال اور اولاد — والے تھے — انہوں نے — اپنی حصے — کی متاع — سے لطف اٹھایا — پس — تم — نے — بھی — اپنی حصے — کی متاع — سے — لطف اٹھایا — جیسے — تم — سے — پہلے والوں نے — اور — تم — اسی طرح — خوض میں پڑ گئے — جیسے — وہ — پڑے — یہ — وہ لوگ ہیں — جن کے — اعمال — دنیا اور آخرت میں — ضائع ہو گئے — اور یہی لوگ — نقصان — پانے والے ہیں",
"""۱۔ گزشتہ اقوام — بھی آج تمہاری طرح — تھے۔
۲۔ ’’كَالَّذِينَ مِن قَبْلِكُمْ كَانُوا أَشَدَّ مِنكُمْ قُوَّۃً وَأَكْثَرَ أَمْوَالًا وَأَوْلَادًا فَاسْتَمْتَعُوا بِخَلَاقِهِمْ فَاسْتَمْتَعْتُم بِخَلَاقِكُمْ كَمَا اسْتَمْتَعَ الَّذِينَ مِن قَبْلِكُمْ بِخَلَاقِهِمْ وَخُضْتُمْ كَالَّذِي خَاضُوا أُولَٰئِكَ حَبِطَتْ أَعْمَالُهُمْ فِي الدُّنْيَا وَالْآخِرَۃِ وَأُولَٰئِكَ هُمُ الْخَاسِرُونَ‘‘ — جیسے — تم — سے — پہلے والے — وہ — تمہارے سے — زیادہ طاقتور — اور — زیادہ مال اور اولاد — والے تھے — انہوں نے — اپنی حصے — کی متاع — سے لطف اٹھایا — پس — تم — نے — بھی — اپنی حصے — کی متاع — سے — لطف اٹھایا — جیسے — تم — سے — پہلے والوں نے — اور — تم — اسی طرح — خوض میں پڑ گئے — جیسے — وہ — پڑے — یہ — وہ لوگ ہیں — جن کے — اعمال — دنیا اور آخرت میں — ضائع ہو گئے — اور یہی لوگ — نقصان — پانے والے ہیں — یعنی منافق — گزشتہ اقوام کی — طرح — دنیا میں لطف اٹھاتے ہیں اور — آخرت میں — خسارہ پاتے ہیں۔
۳۔ عملی سبق: دنیا کی لذت — آخرت کی خسارے — کا سبب ہے۔"""
),
1305: (
"کیا — ان — کے پاس — ان — سے — پہلے والوں کی — خبر — نہیں پہنچی — نوح کی قوم — عاد — ثمود — ابراہیم کی قوم — مدین کے رہنے والے — اور — الٹی ہوئی بستیاں — ان کے پاس — ان کے — رسول — واضح نشانیاں — لے کر آئے — پس — اللہ — نے — ان — پر — ظلم نہیں کیا — لیکن — وہ — خود اپنی جانوں — پر ظلم کرتے تھے",
"""۱۔ تاریخ — نصیحت — کا سب سے بڑا ذریعہ۔
۲۔ ’’أَلَمْ يَأْتِهِمْ نَبَأُ الَّذِينَ مِن قَبْلِهِمْ قَوْمُ نُوحٍ وَعَادٍ وَثَمُودَ وَقَوْمُ إِبْرَاهِيمَ وَأَصْحَابُ مَدْيَنَ وَالْمُؤْتَفِكَاتِ أَتَتْهُمْ رُسُلُهُم بِالْبَيِّنَاتِ فَمَا كَانَ اللَّهُ لِيَظْلِمَهُمْ وَلَٰكِن كَانُوا أَنفُسَهُمْ يَظْلِمُونَ‘‘ — کیا — ان — کے پاس — ان — سے — پہلے والوں کی — خبر — نہیں پہنچی — نوح کی قوم — عاد — ثمود — ابراہیم کی قوم — مدین کے رہنے والے — اور — الٹی ہوئی بستیاں — ان کے پاس — ان کے — رسول — واضح نشانیاں — لے کر آئے — پس — اللہ — نے — ان — پر — ظلم نہیں کیا — لیکن — وہ — خود اپنی جانوں — پر ظلم کرتے تھے — یعنی گزشتہ اقوام — ہلاک ہوئیں — اپنی — گناہوں — کی وجہ سے۔
۳۔ عملی سبق: تاریخ سے عبرت حاصل کرو؛ ظلم — ہمیشہ — خود کو — نقصان پہنچاتا ہے۔"""
),
1306: (
"اور — مؤمن مرد اور مؤمن عورتیں — ایک دوسرے کے — کارساز ہیں — وہ — بھلائی کا حکم دیتے ہیں — اور — برائی سے روکتے ہیں — اور — نماز قائم کرتے ہیں — اور زکوٰۃ دیتے ہیں — اور — اللہ اور اس کے رسولؐ — کی اطاعت کرتے ہیں — یہی لوگ — عنقریب اللہ — ان پر — رحم کرے گا — بے شک — اللہ — زبردست حکمت والا ہے",
"""۱۔ مؤمنین کی — حقیقی صفات — بھلائی کا حکم، برائی سے روک، نماز، زکوٰۃ، اطاعت۔
۲۔ ’’وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلَاۃَ وَيُؤْتُونَ الزَّكَاۃَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُولَٰئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ‘‘ — اور — مؤمن مرد اور مؤمن عورتیں — ایک دوسرے کے — کارساز ہیں — وہ — بھلائی کا حکم دیتے ہیں — اور — برائی سے روکتے ہیں — اور — نماز قائم کرتے ہیں — اور زکوٰۃ دیتے ہیں — اور — اللہ اور اس کے رسولؐ — کی اطاعت کرتے ہیں — یہی لوگ — عنقریب اللہ — ان پر — رحم کرے گا — بے شک — اللہ — زبردست حکمت والا ہے — یعنی مؤمن — ایک دوسرے کے — ولی ہیں — بھلائی کا حکم اور برائی سے روک — ان کا — مستقل — کام — ہے۔
۳۔ عملی سبق: نہ صرف خود عمل کرو — بلکہ — دوسروں کو بھی — بھلائی کی دعوت دو۔"""
),
1307: (
"اللہ — مؤمن مردوں اور مؤمن عورتوں — کو — ایسی جنتوں — کا وعدہ دیتا ہے — جن — کے نیچے نہریں بہہتی ہیں — وہ — ان میں ہمیشہ رہیں گے — اور — پاک مکانات — عدن کی جنتوں میں — اور — اللہ کی طرف سے — رضوان — سب سے بڑا ہے — یہی — عظیم — کامیابی — ہے",
"""۱۔ مؤمنوں کے لیے — اللہ کی خوش خبری۔
۲۔ ’’وَعَدَ اللَّهُ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا وَمَسَاكِنَ طَيِّبَۃً فِي جَنَّاتِ عَدْنٍ وَرِضْوَانٌ مِّنَ اللَّهِ أَكْبَرُ ذَٰلِكَ هُوَ الْفَوْزُ الْعَظِيمُ‘‘ — اللہ — مؤمن مردوں اور مؤمن عورتوں — کو — ایسی جنتوں — کا وعدہ دیتا ہے — جن — کے نیچے نہریں بہہتی ہیں — وہ — ان میں ہمیشہ رہیں گے — اور — پاک مکانات — عدن کی جنتوں میں — اور — اللہ کی طرف سے — رضوان — سب سے بڑا ہے — یہی — عظیم — کامیابی — ہے — یعنی اللہ — مؤمنوں کو جو — ملے گا — اس سے بڑھ کر — اللہ کی رضا — ہے۔
۳۔ عملی سبق: اللہ کی رضا — سب سے بڑی کامیابی — ہے۔"""
),
1308: (
"اے نبیؐ — کافروں اور منافقوں — سے جہاد کرو — اور — ان پر — سختی کرو — اور — ان کا ٹھکانا — جہنم ہے — اور — وہ — بدترین انجام ہے",
"""۱۔ جہاد — کافروں اور منافقوں — دونوں سے۔
۲۔ ’’يَا أَيُّهَا النَّبِيُّ جَاهِدِ الْكُفَّارَ وَالْمُنَافِقِينَ وَاغْلُظْ عَلَيْهِمْ وَمَأْوَاهُمْ جَهَنَّمُ وَبِئْسَ الْمَصِيرُ‘‘ — اے نبیؐ — کافروں اور منافقوں — سے جہاد کرو — اور — ان پر — سختی کرو — اور — ان کا ٹھکانا — جہنم ہے — اور — وہ — بدترین انجام ہے — یعنی کافروں سے جنگ — اور منافقوں سے — سختی (اور جھگڑا) — دونوں — لازم ہیں۔
۳۔ عملی سبق: کفر سے جنگ اور نفاق سے سختی — دونوں — اسلام کی حفاظت کا — حصہ ہیں۔"""
),
1309: (
"وہ — اللہ کی قسم — کھاتے ہیں — کہ — انہوں نے نہیں کہا — حالانکہ — انہوں نے — کفر کی بات — ہی کہی — اور — اپنے اسلام کے بعد — کفر کیا — اور — انہوں نے — وہ ارادہ کیا — جو — انہیں حاصل نہیں ہوا — اور — ان کا — کوئی نقصان نہیں ہوتا — مگر — یہ — کہ اللہ اور اس کے رسولؐ — نے — اپنے فضل سے — انہیں — بے نیاز کر دیا — پس — اگر — وہ — توبہ کریں — تو یہ — ان کے لیے — بہتر ہے — اور — اگر — وہ — منہ موڑیں — تو — اللہ — انہیں — دنیا اور آخرت میں — دردناک عذاب — دے گا — اور — ان کے لیے — زمین میں — کوئی ولی — ہے — نہ — کوئی مددگار",
"""۱۔ منافق — قسم کھانے والے جھوٹے۔
۲۔ ’’يَحْلِفُونَ بِاللَّهِ مَا قَالُوا وَلَقَدْ قَالُوا كَلِمَۃَ الْكُفْرِ وَكَفَرُوا بَعْدَ إِسْلَامِهِمْ وَهَمُّوا بِمَا لَمْ يَنَالُوا وَمَا نَقَمُوا إِلَّا أَنْ أَغْنَاهُمُ اللَّهُ وَرَسُولُهُ مِن فَضْلِهِ فَإِن يَتُوبُوا يَكُ خَيْرًا لَّهُمْ وَإِن يَتَوَلَّوْا يُعَذِّبْهُمُ اللَّهُ عَذَابًا أَلِيمًا فِي الدُّنْيَا وَالْآخِرَۃِ وَمَا لَهُمْ فِي الْأَرْضِ مِن وَلِيٍّ وَلَا نَصِيرٍ‘‘ — وہ — اللہ کی قسم — کھاتے ہیں — کہ — انہوں نے نہیں کہا — حالانکہ — انہوں نے — کفر کی بات — ہی کہی — اور — اپنے اسلام کے بعد — کفر کیا — اور — انہوں نے — وہ ارادہ کیا — جو — انہیں حاصل نہیں ہوا — اور — ان کا — کوئی نقصان نہیں ہوتا — مگر — یہ — کہ اللہ اور اس کے رسولؐ — نے — اپنے فضل سے — انہیں — بے نیاز کر دیا — پس — اگر — وہ — توبہ کریں — تو یہ — ان کے لیے — بہتر ہے — اور — اگر — وہ — منہ موڑیں — تو — اللہ — انہیں — دنیا اور آخرت میں — دردناک عذاب — دے گا — اور — ان کے لیے — زمین میں — کوئی ولی — ہے — نہ — کوئی مددگار — یعنی منافق — کفر کی بات کر کے — پھر — انکار کر دیتے ہیں — ان کا اصل مسئلہ — نبیؐ کا شکر ادا کرنے کا ہے۔
۳۔ عملی سبق: نعمتِ الٰہی کی ناشکری — دنیا اور آخرت میں سزا کا سبب ہے۔"""
),
}
